mapper.select:
select count(1) from `ry_rental`.`ry_rental_accessory`
where accessory_code = #{accessoryCode} and is_delete = 0
and accessory_id != #{excludeAccessoryId}

mapper.update:
update `ry_rental`.`ry_rental_accessory_model`
set is_delete = 1, update_by = #{operator}
where accessory_id = #{accessoryId} and is_delete = 0
